package gallery

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// morseFixture is the repository's synthetic CW reference, generated by
// tools/gen_test_wavs.py keying "CQ DE RS44 SAT" at 60 ms per dot on a
// 700 Hz tone (see internal/decode TestMorseReference).
const morseFixture = "../../../tests/data/ref_morse.wav"

// CW-labelled audio decodes into a text artefact carrying the gated
// transcript, with lineage and provenance preserved.
func TestDecodeFramesMorseReference(t *testing.T) {
	if _, err := os.Stat(morseFixture); err != nil {
		t.Fatal("committed CW reference fixture missing - the positive decode test must not silently skip:", err)
	}
	dir := t.TempDir()
	name := "997-audio.wav"
	data, err := os.ReadFile(morseFixture)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, name), data, 0o644); err != nil {
		t.Fatal(err)
	}
	items := []Item{{
		Source: "satnogs", ObservationURL: ObservationLink(997), ObservationID: 997,
		Satellite: "RS-44", NoradID: 44909, Station: "test-station",
		Start: time.Unix(1_700_000_000, 0), Mode: "CW", FrequencyHz: 435_640_000,
		Kind: "audio", Name: name, Path: filepath.Join(dir, name),
	}}
	frames := DecodeFrames(items, dir)
	if len(frames) != 1 {
		t.Fatalf("got %d artefacts, want 1 decoded text artefact (source status %q)", len(frames), items[0].DecodeStatus)
	}
	frame := frames[0]
	if frame.Kind != "text" || frame.DecodedFrom != name || !strings.HasSuffix(frame.Name, "-sdrstream-decoded.txt") {
		t.Fatalf("artefact lineage wrong: %+v", frame)
	}
	if frame.Source != "satnogs" || frame.ObservationID != 997 || frame.Station != "test-station" {
		t.Fatalf("provenance not carried to the decoded artefact: %+v", frame)
	}
	content, err := os.ReadFile(frame.Path)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(content), "CQ DE RS44 SAT") {
		t.Fatalf("transcript missing the keyed reference text, got:\n%s", content)
	}
	if !strings.Contains(string(content), "not independently verified") {
		t.Fatal("artefact must label the transcript as not independently verified")
	}
	if frame.Text == "" {
		t.Fatal("text artefact carries no inline preview; the web UI renders it.text")
	}
	if items[0].DecodeStatus != "" {
		t.Fatalf("source item unexpectedly marked: %q", items[0].DecodeStatus)
	}
}

// Non-beacon audio labelled CW produces no artefact: the plausibility
// gate, not guesswork, decides there is no readable Morse. APRS packet
// audio keys elements near 0.8 ms - far under the 25 ms beacon floor.
func TestDecodeFramesMorseNoPlausibleRead(t *testing.T) {
	if _, err := os.Stat(realAPRSFixture); err != nil {
		t.Skip("off-air APRS fixture not present:", err)
	}
	dir := t.TempDir()
	name := "996-audio.wav"
	data, err := os.ReadFile(realAPRSFixture)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, name), data, 0o644); err != nil {
		t.Fatal(err)
	}
	items := []Item{{Kind: "audio", Mode: "CW", Name: name, Path: filepath.Join(dir, name)}}
	if frames := DecodeFrames(items, dir); len(frames) != 0 {
		t.Fatalf("got %d artefacts from non-beacon audio, want 0", len(frames))
	}
	if !strings.Contains(items[0].DecodeStatus, "no plausible Morse") {
		t.Fatalf("unexpected status %q, want a no-plausible-Morse note", items[0].DecodeStatus)
	}
}
